const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const states = ee.FeatureCollection('FAO/GAUL/2015/level1');
  const punjabHaryana = states.filter(ee.Filter.inList('ADM1_NAME', ['Punjab', 'Haryana']));

  const startYear = 2012;
  const endYear = 2023;
  const targetYear = 2024;

  const collection = ee.ImageCollection('FIRMS/VIIRS/VNP14IMGTDL_NRT');

  let fireCountsPreviousYears = [];
  let november2024FireCount = null;
  let minPreviousNovemberCount = Infinity;

  try {
    // Process previous Novembers (2012-2023)
    for (let year = startYear; year <= endYear; year++) {
      const startDate = ee.Date.fromYMD(year, 11, 1);
      const endDate = ee.Date.fromYMD(year, 11, 30);

      const filteredCollection = collection
        .filterDate(startDate, endDate)
        .filterBounds(punjabHaryana);

      const count = await filteredCollection.size().getInfo();
      fireCountsPreviousYears.push(count);

      if (count < minPreviousNovemberCount) {
        minPreviousNovemberCount = count;
      }
      console.log(`November ${year} Fires: ${count}`);
    }

    // Check if any previous year had data. If all were 0, minPreviousNovemberCount would still be Infinity or 0.
    if (fireCountsPreviousYears.every(c => c === 0)) {
        console.log("No fires detected in Punjab and Haryana for any November from 2012-2023.");
    } else if (fireCountsPreviousYears.length === 0) {
        console.log("Error: No data retrieved for previous Novembers.");
        console.log("C3"); // Should not happen if loop completes
        return;
    }

    // Process November 2024
    const targetStartDate = ee.Date.fromYMD(targetYear, 11, 1);
    const targetEndDate = ee.Date.fromYMD(targetYear, 11, 30); // Use 30 for full month comparison

    const targetCollection = collection
      .filterDate(targetStartDate, targetEndDate)
      .filterBounds(punjabHaryana);

    november2024FireCount = await targetCollection.size().getInfo();
    console.log(`November ${targetYear} Fires: ${november2024FireCount}`);

    // 5. Validation & Final Answer
    if (fireCountsPreviousYears.length === 0 || minPreviousNovemberCount === Infinity) {
      console.log("C1"); // No data for historical period.
      return;
    }
    if (november2024FireCount === null || isNaN(november2024FireCount)) {
      console.log("C3"); // Calculation for 2024 failed.
      return;
    }

    // Determine if 2024 count is lower than ANY other November
    if (november2024FireCount < minPreviousNovemberCount) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.log(`An error occurred: ${error.message}`);
    console.log("D"); // General error or memory issue
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
